+
+  .contact-form,
+  input {
+    border-color: CanvasText;
+  }
+
+  button,
+  .skip-link {
+    color: ButtonText;
+    background: ButtonFace;
+    border: 1px solid ButtonBorder;
+  }
+
+  input:focus,
+  button:focus,
+  .skip-link:focus {
+    outline: 3px solid Highlight;
+    box-shadow: none;
+  }
+}
*** Add File: script.js
+const form = document.querySelector("#support-form");
+const statusMessage = document.querySelector("#form-status");
+const fields = Array.from(form.querySelectorAll("input"));
+
+function updateInvalidState(field) {
+  if (field.validity.valid) {
+    field.removeAttribute("aria-invalid");
+    return;
+  }
+
+  field.setAttribute("aria-invalid", "true");
+}
+
+fields.forEach((field) => {
+  field.addEventListener("input", () => {
+    if (field.hasAttribute("aria-invalid")) {
+      updateInvalidState(field);
+    }
+
+    statusMessage.textContent = "";
+  });
+});
+
+form.addEventListener("submit", (event) => {
+  event.preventDefault();
+  statusMessage.textContent = "";
+
+  if (!form.checkValidity()) {
+    fields.forEach(updateInvalidState);
+    const firstInvalidField = fields.find((field) => !field.validity.valid);
+
+    if (firstInvalidField) {
+      firstInvalidField.focus();
+      form.reportValidity();
+    }
+
+    return;
+  }
+
+  fields.forEach((field) => field.removeAttribute("aria-invalid"));
+  form.reset();
+  statusMessage.textContent = "Thanks. Your support request is ready to send.";
+});
*** End Patch
