+  font-weight: 800;
+  letter-spacing: 0.12em;
+  text-transform: uppercase;
+}
+
+.page-shell {
+  width: min(68rem, 100%);
+  min-height: calc(100vh - 5rem);
+  margin: 0 auto;
+  padding: clamp(2rem, 7vw, 5rem) clamp(1rem, 4vw, 2rem);
+  display: grid;
+  align-items: center;
+}
+
+.hero {
+  display: grid;
+  grid-template-columns: minmax(0, 0.9fr) minmax(18rem, 1fr);
+  gap: clamp(2rem, 6vw, 5rem);
+  align-items: center;
+}
+
+.hero-copy,
+.contact-form {
+  min-width: 0;
+}
+
+h1 {
+  margin: 0.6rem 0 1rem;
+  font-size: clamp(2.4rem, 8vw, 5rem);
+  line-height: 0.95;
+  letter-spacing: -0.06em;
+}
+
+.intro {
+  max-width: 35rem;
+  margin: 0;
+  color: var(--muted);
+  font-size: clamp(1rem, 2vw, 1.2rem);
+}
+
+.contact-form {
+  padding: clamp(1.25rem, 4vw, 2rem);
+  border: 1px solid var(--panel-border);
+  border-radius: 1.5rem;
+  background: linear-gradient(180deg, #111c2e 0%, #0d1728 100%);
+  box-shadow: 0 1.5rem 4rem var(--shadow);
+}
+
+.form-field {
+  display: grid;
+  gap: 0.45rem;
+  margin-bottom: 1.15rem;
+}
+
+label {
+  font-weight: 750;
+  color: var(--text);
+}
+
+.optional,
+.helper-text {
+  color: var(--muted);
+}
+
+.optional {
+  font-weight: 500;
+}
+
+input {
+  width: 100%;
+  min-height: 3rem;
+  padding: 0.8rem 0.9rem;
+  border: 1px solid var(--input-border);
+  border-radius: 0.9rem;
+  color: var(--text);
+  background: var(--input-bg);
+  font: inherit;
+}
+
+input:hover {
+  border-color: var(--accent);
+}
+
+input:focus,
+button:focus,
+.skip-link:focus {
+  outline: 3px solid transparent;
+  box-shadow: 0 0 0 3px var(--page-bg), 0 0 0 6px var(--accent-strong);
+}
+
+input[aria-invalid="true"] {
+  border-color: var(--invalid);
+}
+
+.helper-text,
+.form-status {
+  margin: 0;
+  font-size: 0.92rem;
+}
+
+button {
+  width: 100%;
+  min-height: 3.25rem;
+  margin-top: 0.25rem;
+  border: 0;
+  border-radius: 999px;
+  color: var(--button-text);
+  background: var(--button-bg);
+  font: inherit;
+  font-weight: 850;
+  cursor: pointer;
+}
+
+button:hover {
+  background: var(--button-hover);
+}
+
+.form-status {
+  min-height: 1.4rem;
+  margin-top: 1rem;
+  color: var(--accent);
+  font-weight: 700;
+}
+
+@media (max-width: 44rem) {
+  .hero {
+    grid-template-columns: 1fr;
+  }
+}
+
+@media (forced-colors: active) {
+  body,
+  .contact-form,
+  input {
+    color: CanvasText;
+    background: Canvas;
+  }
+
+  .contact-form,
+  input {
+    border-color: CanvasText;
+  }
+
+  button,
+  .skip-link {
+    color: ButtonText;
+    background: ButtonFace;
+    border: 1px solid ButtonBorder;
+  }
+
+  input:focus,
+  button:focus,
+  .skip-link:focus {
+    outline: 3px solid Highlight;
+    box-shadow: none;
+  }
+}
+



